// Luxon is available in the Code node as DateTime. Run the window in the
// business's own timezone - "yesterday" in UTC is not "yesterday" in Sydney.
const zone = $env.RECONCILIATION_TIMEZONE || 'Australia/Sydney';
const start = DateTime.now().setZone(zone).minus({ days: 1 }).startOf('day');
const end = start.endOf('day');

return [
  {
    json: {
      timezone: zone,
      business_date: start.toISODate(),
      from_iso: start.toUTC().toISO(),
      to_iso: end.toUTC().toISO(),
      from_unix: Math.floor(start.toSeconds()),
      to_unix: Math.floor(end.toSeconds()),
    },
  },
];

// Webhooks are best-effort. This is the net under them: whatever the live
// workflows missed shows up here the same night, not in a refund request.
const window = $('Yesterday Window').first().json;

const paymentsResponse = $('Fetch Yesterdays Payments').first().json || {};
const enrolmentsResponse = $('Fetch Thinkific Enrolments').first().json || {};

const payments = (paymentsResponse.data || paymentsResponse.items || [])
  .filter((p) => (p.status || '').toLowerCase() === 'succeeded' || p.paid === true);
const enrolments = enrolmentsResponse.items || enrolmentsResponse.data || [];

const normalise = (value) => String(value || '').toLowerCase().trim();

const enrolledEmails = new Set(
  enrolments.map((e) => normalise(e.user_email || (e.user && e.user.email))),
);
const paidEmails = new Set(
  payments.map((p) => normalise(p.billing_details && p.billing_details.email ? p.billing_details.email : p.receipt_email || p.customer_email)),
);

const missingEnrolments = payments
  .filter((p) => {
    const email = normalise(p.billing_details && p.billing_details.email ? p.billing_details.email : p.receipt_email || p.customer_email);
    return email && !enrolledEmails.has(email);
  })
  .map((p) => ({
    email: normalise(p.billing_details && p.billing_details.email ? p.billing_details.email : p.receipt_email || p.customer_email),
    charge_id: p.id,
    amount_cents: p.amount || p.amount_captured || null,
    currency: p.currency || null,
  }));

const orphanEnrolments = enrolments
  .filter((e) => {
    const email = normalise(e.user_email || (e.user && e.user.email));
    return email && !paidEmails.has(email);
  })
  .map((e) => ({
    email: normalise(e.user_email || (e.user && e.user.email)),
    enrolment_id: e.id,
    course_id: e.course_id || null,
  }));

return [
  {
    json: {
      business_date: window.business_date,
      timezone: window.timezone,
      payments_checked: payments.length,
      enrolments_checked: enrolments.length,
      missing_enrolments: missingEnrolments,
      orphan_enrolments: orphanEnrolments,
      discrepancy_count: missingEnrolments.length + orphanEnrolments.length,
    },
  },
];

